// Normalize and validate incoming lead payload.
// Accepts payloads from HubSpot, Pipedrive, Apollo, or a generic form.
// Fails fast with a structured error if required fields are missing.

const body = $input.first().json.body || $input.first().json;

const lead = {
  first_name: body.first_name || body.firstName || body.first || '',
  last_name:  body.last_name  || body.lastName  || body.last  || '',
  email:      body.email || '',
  company:    body.company || body.company_name || body.organization || '',
  role:       body.title || body.job_title || body.role || '',
  signal:     body.signal || body.trigger || body.source || 'inbound',
  linkedin:   body.linkedin_url || body.linkedin || '',
  notes:      body.notes || ''
};

const missing = ['first_name','company','email'].filter(k => !lead[k]);
if (missing.length) {
  throw new Error(`Missing required lead fields: ${missing.join(', ')}`);
}

lead.full_name = `${lead.first_name} ${lead.last_name}`.trim();
lead.received_at = new Date().toISOString();

return [{ json: lead }];

// Build the prompt context for the LLM.
// Merge raw lead with Apollo enrichment (if any) and produce a tight system+user prompt pair.

const lead = $('Normalize Lead').first().json;
const enrichment = $input.first().json?.person || {};

const context = {
  name: lead.full_name,
  company: lead.company,
  role: enrichment.title || lead.role || 'Unknown',
  seniority: enrichment.seniority || '',
  industry: enrichment.organization?.industry || '',
  company_size: enrichment.organization?.estimated_num_employees || '',
  signal: lead.signal,
  notes: lead.notes
};

const system_prompt = `You are a senior SDR writing a 30-second voicemail script.
Rules:
- Open with the prospect's first name, your name ("Sam from Lumen"), and a personalized hook from the signal.
- One value claim tied to their role/industry. No generic platitudes.
- One specific ask ("15-minute call this week").
- Output ONLY the spoken script. No labels, no stage directions, no XML.
- 70-95 words. Warm, conversational, no jargon.`;

const user_prompt = `Prospect:
- Name: ${context.name}
- Role: ${context.role}${context.seniority ? ' ('+context.seniority+')' : ''}
- Company: ${context.company}${context.industry ? ' — '+context.industry : ''}${context.company_size ? ', ~'+context.company_size+' employees' : ''}

Signal that triggered outreach: ${context.signal}
${context.notes ? 'Internal note: '+context.notes : ''}

Write the voicemail.`;

return [{ json: { ...lead, context, system_prompt, user_prompt } }];

// Extract OpenAI's text output and validate length.
// If the script is malformed or too long for ElevenLabs sweet spot, throw to error branch.

const response = $input.first().json;
const script = response.choices?.[0]?.message?.content?.trim();

if (!script) {
  throw new Error(`OpenAI returned no script. Full response: ${JSON.stringify(response).slice(0, 500)}`);
}

const word_count = script.split(/\s+/).length;
if (word_count < 40 || word_count > 130) {
  throw new Error(`Script length out of bounds (${word_count} words). Expected 70-95.`);
}

// Pull in the original lead so it flows downstream.
const lead = $('Build Prompt').first().json;

return [{ json: { ...lead, script, word_count, tokens_in: response.usage?.prompt_tokens, tokens_out: response.usage?.completion_tokens } }];

// Reconstruct the R2 audio URL from the SAME deterministic path Upload to S3 used.
// Inputs: email + received_at (both immutable on the lead from Normalize Lead).
// This works because the n8n 'S3' node returns only { success: true } — no Bucket/Key.

const lead = $('Parse + Validate Script').first().json;
const upload = $input.first()?.json || {};

// EDIT THIS to your R2 public URL — looks like https://pub-XXXXXXXXXXXX.r2.dev
const R2_PUBLIC_BASE = 'https://pub-ee5550efd4674005848220beb733c794.r2.dev';

const emailKey = lead.email.replace('@', '_at_');
const ts = lead.received_at.replace(/[:T.Z-]/g, '').slice(0, 14);
const expectedKey = `outreach/${emailKey}/${ts}.mp3`;

let audio_url;
if (upload.success && !R2_PUBLIC_BASE.includes('REPLACE_ME')) {
  audio_url = `${R2_PUBLIC_BASE}/${expectedKey}`;
} else if (upload.Location) {
  audio_url = upload.Location;
} else {
  audio_url = 'pending-upload (S3 node deactivated or R2_PUBLIC_BASE not set)';
}

return [{
  json: {
    lead_name: lead.full_name,
    email: lead.email,
    company: lead.company,
    role: lead.context.role,
    script: lead.script,
    word_count: lead.word_count,
    audio_url,
    tokens_in: lead.tokens_in,
    tokens_out: lead.tokens_out,
    estimated_cost_usd: ((lead.tokens_in * 2.5 + lead.tokens_out * 10) / 1_000_000).toFixed(4),
    generated_at: new Date().toISOString(),
    status: 'ready_to_send'
  }
}];

